use std::collections::{HashMap,VecDeque};struct LRUCache{cap:usize,map:HashMap<i32,i32>,order:VecDeque<i32>}impl LRUCache{fn new(capacity:i32)->Self{Self{cap:capacity as usize,map:HashMap::new(),order:VecDeque::new()}}fn touch(&mut self,k:i32){if let Some(i)=self.order.iter().position(|&x|x==k){self.order.remove(i);}self.order.push_front(k);}fn get(&mut self,key:i32)->i32{if let Some(&v)=self.map.get(&key){self.touch(key);v}else{-1}}fn put(&mut self,key:i32,value:i32){if !self.map.contains_key(&key)&&self.map.len()==self.cap{if let Some(k)=self.order.pop_back(){self.map.remove(&k);}}self.map.insert(key,value);self.touch(key);}}
